sys_script_include.script:
var SessionDef = Class.create();

/**
 * Used to initialize a SessionDef record and script
 * @param {Object} fieldMap : Javascript object of key value pairs of every field to initialize
 *  Values can be function to evaluate
 */
SessionDef.initialize = function(fieldMap){
	var script = new SessionDef();
	var record = new GlideRecord(script.TABLE_NAME);
	record.initialize();
	for (field in fieldMap){
		let value = fieldMap[field];
		if (typeof(value) == "function")
			record.setValue(field, value());
		else record.setValue(field, value);
	}
	script.r = record;
	return script;
};
SessionDef.new = function(fieldMap){
	var script = SessionDef.initialize(fieldMap);
	script.r.insert();
	return script;
};

SessionDef.prototype = {
	TABLE_NAME: "x_776055_workout_session_definition",

	/**
	 * @param {GlideRecord|GlideElement|String} record : Used to initialize current record (this.r).
	 * 	can be either a gliderecord, a glideElement or a sys_id
	 */
    initialize: function(record) {
		if (record && record.getUniqueValue())
            this.r = record;
        else if (record)
            this.r = new GlideRecordUtil().getGR(this.TABLE_NAME, record);
    },

	generateSession: function(){

	},

    type: 'SessionDef'
};
